    rows: [["I have lived here for five years.", "besh yildan beri shu yerda yashayman"], ["I've known him since 2019.", "uni 2019-yildan beri taniyman"], ["How long have you worked here?", "qancha vaqtdan beri shu yerda ishlaysan?"], ["I worked there in 2020.", "2020-yilda u yerda ishlaganman (tugagan)"]],
    note: "for + vaqt uzunligi (for two hours, for a year), since + boshlangan payt (since Monday, since 2020, since I was a child).",
    ex: [["I've studied English for two years.", "Ikki yildan beri ingliz tili o'qiyman."], ["She has been sick since Monday.", "U dushanbadan beri kasal."], ["We met in 2021.", "Biz 2021-yilda tanishganmiz."]],
